import os
import json
import logging
from flask import Flask, request, jsonify, Response, stream_with_context, send_file
from flask_cors import CORS
from werkzeug.exceptions import BadRequest
import anthropic
from anthropic import Anthropic

def get_required_env(name):
    value = os.environ.get(name)
    if value is None or not str(value).strip():
        raise RuntimeError(f"Environment variable {name} is required and must be a non-empty string.")
    return str(value).strip()

def get_optional_env(name, default):
    value = os.environ.get(name, default)
    if value is None:
        return default
    value = str(value).strip()
    if not value:
        raise RuntimeError(f"Environment variable {name} must be a non-empty string.")
    return value

def get_int_env(name, default, minimum=None, maximum=None):
    raw_value = os.environ.get(name)
    if raw_value is None or str(raw_value).strip() == "":
        value = default
    else:
        try:
            value = int(str(raw_value).strip())
        except (TypeError, ValueError):
            raise RuntimeError(f"Environment variable {name} must be a valid integer.")
    if minimum is not None and value < minimum:
        raise RuntimeError(f"Environment variable {name} must be greater than or equal to {minimum}.")
    if maximum is not None and value > maximum:
        raise RuntimeError(f"Environment variable {name} must be less than or equal to {maximum}.")
    return value

ANTHROPIC_API_KEY = get_required_env("ANTHROPIC_API_KEY")
ANTHROPIC_WORKSPACE_ID = get_required_env("ANTHROPIC_WORKSPACE_ID")
MODEL = get_optional_env("MODEL", "claude-opus-4-7")
MODEL_CONTEXT_WINDOW = get_int_env("MODEL_CONTEXT_WINDOW", 200000, minimum=1024, maximum=1000000)
DEFAULT_MAX_TOKENS = get_int_env("MAX_TOKENS", 128000, minimum=1, maximum=MODEL_CONTEXT_WINDOW - 1)
MAX_OUTPUT_TOKENS_LIMIT = get_int_env("MAX_OUTPUT_TOKENS_LIMIT", DEFAULT_MAX_TOKENS, minimum=1, maximum=MODEL_CONTEXT_WINDOW - 1)
if DEFAULT_MAX_TOKENS > MAX_OUTPUT_TOKENS_LIMIT:
    raise RuntimeError("MAX_TOKENS must be less than or equal to MAX_OUTPUT_TOKENS_LIMIT.")
PORT = get_int_env("PORT", 5000, minimum=1, maximum=65535)

APP_DIR = os.path.dirname(os.path.abspath(__file__))
INDEX_PATH = os.path.join(APP_DIR, "index.html")

app = Flask(__name__)
app.config["JSON_AS_ASCII"] = False
CORS(app)
app.logger.setLevel(logging.INFO)

def get_client():
    return Anthropic(
        api_key=ANTHROPIC_API_KEY,
        default_headers={
            "anthropic-workspace-id": ANTHROPIC_WORKSPACE_ID
        },
    )

def json_error(message, status_code, details=None):
    payload = {"error": {"message": message}}
    if details is not None:
        payload["error"]["details"] = details
    response = jsonify(payload)
    return response, status_code

def sse_event(payload):
    return f"data: {json.dumps(payload, ensure_ascii=False)}\n\n"

def normalize_max_tokens(value):
    if value is None:
        return DEFAULT_MAX_TOKENS
    if isinstance(value, bool):
        raise ValueError("The max_tokens field must be an integer.")
    try:
        normalized = int(value)
    except (TypeError, ValueError):
        raise ValueError("The max_tokens field must be an integer.")
    if normalized < 1:
        raise ValueError("The max_tokens field must be greater than or equal to 1.")
    if normalized > MAX_OUTPUT_TOKENS_LIMIT:
        raise ValueError(f"The max_tokens field must be less than or equal to {MAX_OUTPUT_TOKENS_LIMIT}.")
    if normalized >= MODEL_CONTEXT_WINDOW:
        raise ValueError("The max_tokens field must be smaller than MODEL_CONTEXT_WINDOW.")
    return normalized

def parse_chat_request():
    try:
        data = request.get_json(force=True, silent=False, cache=False)
    except BadRequest as exc:
        return None, json_error("Invalid JSON body.", 400, {"reason": str(exc)})
    if data is None:
        return None, json_error("Request body must contain JSON.", 400)
    if not isinstance(data, dict):
        return None, json_error("The JSON root element must be an object.", 400)
    if "messages" not in data:
        return None, json_error("The messages field is required.", 400)
    messages = data.get("messages")
    if not isinstance(messages, list):
        return None, json_error("The messages field must be a list.", 400)
    if not messages:
        return None, json_error("The messages list must not be empty.", 400)
    system_prompt = data.get("system", "")
    if system_prompt is None:
        system_prompt = ""
    if not isinstance(system_prompt, str):
        return None, json_error("The system field must be a string.", 400)
    try:
        max_tokens = normalize_max_tokens(data.get("max_tokens"))
    except ValueError as exc:
        return None, json_error(str(exc), 400)
    anthropic_messages = []
    user_message_count = 0
    for index, item in enumerate(messages):
        if not isinstance(item, dict):
            return None, json_error(f"Message at index {index} must be an object.", 400)
        role = item.get("role")
        if role not in ("user", "assistant"):
            return None, json_error(f"Message at index {index} has an invalid role.", 400, {"allowed_roles": ["user", "assistant"]})
        content = item.get("content")
        if not isinstance(content, str):
            return None, json_error(f"Message at index {index} content must be a string.", 400)
        normalized_content = content.strip()
        if not normalized_content:
            return None, json_error(f"Message at index {index} content must not be empty.", 400)
        anthropic_messages.append({"role": role, "content": normalized_content})
        if role == "user":
            user_message_count += 1
    if user_message_count == 0:
        return None, json_error("At least one user message is required.", 400)
    return {
        "system_prompt": system_prompt,
        "messages": anthropic_messages,
        "max_tokens": max_tokens,
    }, None

def count_input_tokens(client, system_prompt, messages):
    kwargs = {
        "model": MODEL,
        "messages": messages,
    }
    if system_prompt:
        kwargs["system"] = system_prompt
    result = client.messages.count_tokens(**kwargs)
    return int(result.input_tokens)

def fit_messages_to_context(client, system_prompt, messages, max_tokens):
    available_input_tokens = MODEL_CONTEXT_WINDOW - max_tokens
    if available_input_tokens < 1:
        raise ValueError("The configured context window does not leave room for input tokens.")
    working_messages = list(messages)
    dropped_messages = 0
    input_tokens = count_input_tokens(client, system_prompt, working_messages)
    while input_tokens > available_input_tokens and len(working_messages) > 1:
        working_messages.pop(0)
        dropped_messages += 1
        while len(working_messages) > 1 and working_messages[0]["role"] != "user":
            working_messages.pop(0)
            dropped_messages += 1
        input_tokens = count_input_tokens(client, system_prompt, working_messages)
    if not working_messages or not any(message["role"] == "user" for message in working_messages):
        raise ValueError("The conversation does not contain a usable user message after context trimming.")
    if working_messages[0]["role"] != "user":
        first_user_index = next((index for index, message in enumerate(working_messages) if message["role"] == "user"), None)
        if first_user_index is None:
            raise ValueError("The conversation does not contain a usable user message after context trimming.")
        dropped_messages += first_user_index
        working_messages = working_messages[first_user_index:]
        input_tokens = count_input_tokens(client, system_prompt, working_messages)
    if input_tokens > available_input_tokens:
        raise ValueError(
            f"Input is too large for the configured context window. Estimated input tokens: {input_tokens}. Available input token budget: {available_input_tokens}."
        )
    warnings = []
    if dropped_messages > 0:
        warnings.append(
            {
                "type": "warning",
                "warning": {
                    "code": "context_trimmed",
                    "message": f"The oldest {dropped_messages} message(s) were removed to fit the configured context window.",
                    "dropped_messages": dropped_messages,
                    "input_tokens": input_tokens,
                    "available_input_tokens": available_input_tokens,
                },
            }
        )
    return working_messages, input_tokens, available_input_tokens, warnings

@app.route("/")
def index():
    try:
        if not os.path.isfile(INDEX_PATH):
            raise FileNotFoundError("index.html not found.")
        response = send_file(INDEX_PATH)
        response.headers["Cache-Control"] = "no-store, no-cache, must-revalidate, max-age=0"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
        return response
    except FileNotFoundError:
        return json_error("index.html was not found relative to the application file.", 404)
    except Exception as exc:
        app.logger.exception("Failed to serve index.html")
        return json_error("Failed to serve index.html.", 500, {"reason": str(exc)})

@app.route("/api/chat", methods=["POST"])
def chat():
    parsed, error_response = parse_chat_request()
    if error_response is not None:
        return error_response
    system_prompt = parsed["system_prompt"]
    requested_max_tokens = parsed["max_tokens"]
    try:
        client = get_client()
        prepared_messages, input_tokens, available_input_tokens, warnings = fit_messages_to_context(
            client=client,
            system_prompt=system_prompt,
            messages=parsed["messages"],
            max_tokens=requested_max_tokens,
        )
    except ValueError as exc:
        return json_error(str(exc), 400)
    except anthropic.AuthenticationError as exc:
        app.logger.exception("Anthropic authentication failed during preflight")
        return json_error("Anthropic authentication failed.", 502, {"reason": str(exc)})
    except anthropic.PermissionDeniedError as exc:
        app.logger.exception("Anthropic permission denied during preflight")
        return json_error("Anthropic permission denied.", 502, {"reason": str(exc)})
    except anthropic.APIConnectionError as exc:
        app.logger.exception("Anthropic connection failed during preflight")
        return json_error("Failed to connect to Anthropic.", 503, {"reason": str(exc)})
    except anthropic.APIStatusError as exc:
        app.logger.exception("Anthropic API status error during preflight")
        return json_error("Anthropic API returned an error during preflight.", 502, {"status_code": exc.status_code, "reason": str(exc)})
    except Exception as exc:
        app.logger.exception("Unexpected preflight error")
        return json_error("Unexpected server error during request preflight.", 500, {"reason": str(exc)})

    def generate():
        for warning in warnings:
            yield sse_event(warning)
        try:
            kwargs = {
                "model": MODEL,
                "max_tokens": requested_max_tokens,
                "messages": prepared_messages,
            }
            if system_prompt:
                kwargs["system"] = system_prompt
            with client.messages.stream(**kwargs) as stream:
                for event in stream:
                    event_type = getattr(event, "type", None)
                    if event_type == "content_block_start":
                        content_block = getattr(event, "content_block", None)
                        content_block_type = getattr(content_block, "type", None)
                        if content_block_type and content_block_type != "text":
                            app.logger.warning("Received non-text content block type: %s", content_block_type)
                    elif event_type == "content_block_delta":
                        delta = getattr(event, "delta", None)
                        delta_type = getattr(delta, "type", None)
                        if delta_type == "text_delta":
                            text = getattr(delta, "text", "")
                            if text:
                                yield sse_event({"type": "text", "text": text})
                        elif delta_type:
                            app.logger.warning("Received non-text content delta type: %s", delta_type)
                    elif event_type == "error":
                        error_obj = getattr(event, "error", None)
                        error_code = getattr(error_obj, "type", "stream_error")
                        error_message = getattr(error_obj, "message", "Unknown streaming error.")
                        app.logger.error("Anthropic streaming error event %s: %s", error_code, error_message)
                        yield sse_event({"type": "error", "error": {"code": error_code, "message": error_message}})
                        yield sse_event(
                            {
                                "type": "done",
                                "usage": {
                                    "input_tokens": input_tokens,
                                    "output_tokens": None,
                                },
                                "stop_reason": "error",
                            }
                        )
                        return
                final_message = stream.get_final_message()
                usage = getattr(final_message, "usage", None)
                yield sse_event(
                    {
                        "type": "done",
                        "usage": {
                            "input_tokens": getattr(usage, "input_tokens", input_tokens),
                            "output_tokens": getattr(usage, "output_tokens", None),
                            "available_input_tokens": available_input_tokens,
                        },
                        "stop_reason": getattr(final_message, "stop_reason", None),
                    }
                )
        except anthropic.APIConnectionError as exc:
            app.logger.exception("Anthropic connection error during streaming")
            yield sse_event({"type": "error", "error": {"code": "anthropic_connection_error", "message": str(exc)}})
            yield sse_event({"type": "done", "usage": {"input_tokens": input_tokens, "output_tokens": None}, "stop_reason": "error"})
        except anthropic.APIStatusError as exc:
            app.logger.exception("Anthropic status error during streaming")
            yield sse_event({"type": "error", "error": {"code": "anthropic_api_status_error", "message": str(exc), "status_code": exc.status_code}})
            yield sse_event({"type": "done", "usage": {"input_tokens": input_tokens, "output_tokens": None}, "stop_reason": "error"})
        except Exception as exc:
            app.logger.exception("Unexpected streaming error")
            yield sse_event({"type": "error", "error": {"code": "stream_internal_error", "message": str(exc)}})
            yield sse_event({"type": "done", "usage": {"input_tokens": input_tokens, "output_tokens": None}, "stop_reason": "error"})

    response = Response(
        stream_with_context(generate()),
        mimetype="text/event-stream",
    )
    response.headers["Cache-Control"] = "no-cache"
    response.headers["X-Accel-Buffering"] = "no"
    return response

@app.route("/api/health", methods=["GET"])
def health():
    payload = {
        "status": "ok",
        "model": MODEL,
        "max_tokens": DEFAULT_MAX_TOKENS,
        "max_output_tokens_limit": MAX_OUTPUT_TOKENS_LIMIT,
        "model_context_window": MODEL_CONTEXT_WINDOW,
        "index_html_present": os.path.isfile(INDEX_PATH),
        "workspace_id_present": bool(ANTHROPIC_WORKSPACE_ID),
        "api_key_present": bool(ANTHROPIC_API_KEY),
    }
    try:
        if not os.path.isfile(INDEX_PATH):
            raise FileNotFoundError("index.html not found.")
        client = get_client()
        token_check = client.messages.count_tokens(
            model=MODEL,
            messages=[{"role": "user", "content": "ping"}],
        )
        payload["anthropic"] = {
            "status": "ok",
            "input_tokens": int(token_check.input_tokens),
        }
        return jsonify(payload), 200
    except Exception as exc:
        app.logger.exception("Health check failed")
        payload["status"] = "error"
        payload["anthropic"] = {
            "status": "error",
            "message": str(exc),
        }
        return jsonify(payload), 503

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=PORT, debug=False, threaded=True)
